/* 基于固定上游技能整理的中文阅读卡。
 * 输入、方法与产物为内容归纳；验收提示与协作顺序为本地实践建议，非强制运行契约。
 */
window.MARKETING_CATALOG = Object.fromEntries(Object.entries({
  'product-marketing': ['新项目需要统一定位，或产品、受众发生变化。','产品说明、现有页面、目标用户、竞品、真实证据。','起草产品概览、用户与痛点、差异化、品牌用语；补齐未知，维护版本。','共享产品背景文档与变更记录。','能力、客户、数字有出处；假设与事实区分；其他任务读取同一版本。',['customer-research','copywriting','marketing-plan']],
  'customer-research': ['想知道用户为什么购买、流失、犹豫或选择替代方案。','访谈、问卷、评论、客服记录，或需要调查的问题。','分析现有资料、研究公开讨论，或设计访谈；提炼任务、痛点、原话与矛盾。','研究主题、用户原话、画像、置信度与待验证问题。','保留来源和用户分组；不把模拟访谈当作真实访谈。',['product-marketing','copywriting','cro']],
  'competitor-profiling': ['需要理解特定竞争对手，而非立即写比较页面。','竞品网址、研究范围、自身产品背景。','收集定位、功能、价格、客户证据和内容策略，保留原始资料。','竞品档案、差异、竞争启示及原始来源。','价格和功能标注日期；区分竞品自述、观察和推断。',['product-marketing','competitors','pricing']],
  'marketing-plan': ['要把分散营销工作整理成团队可执行计划。','产品背景、预算、人员、阶段、已有渠道与数据。','调研 → 逐节审阅 → 汇总验证；围绕获客、激活、留存、推荐、收入安排工作。','13 节营销计划、90 天路线、12 个月展望及进度记录。','每项工作有负责人、资源、指标和时机；不把愿景写成已有能力。',['product-marketing','marketing-ideas','analytics']],
  'marketing-council': ['定位、渠道或创意方向需要不同观点的推敲。','明确决策、备选项、产品阶段、约束与现有证据。','选取相关公开框架，保留异议，梳理分歧及能解决分歧的证据。','标明模拟性质的多视角意见、分歧图与建议。','不得捏造名人引语或背书；模拟不能代替真实用户与业务数据。',['product-marketing','offers','ab-testing']],
  'marketing-ideas': ['需要寻找适合当前产品阶段的新策略。','目标、受众、渠道现状、资源和尝试记录。','从策略库选择候选，结合业务适配，形成可尝试方向。','按场景筛选的营销想法与执行起点。','说明机制和适用条件，不把策略数量当成执行进度。',['marketing-plan','marketing-loops','free-tools']],
  'marketing-psychology': ['需要理解用户犹豫、价值感知或决策方式。','具体用户行为、页面或方案，以及已知反馈。','将心理模型映射到决策问题，提出可检查的解释和改动。','行为解释、表达或流程建议及实验假设。','模型只是解释工具；不能为虚假稀缺或无证据的承诺提供借口。',['copywriting','offers','cro']],
  'offers': ['产品有价值，但整套购买理由或方案表达不清晰。','产品、痛点、替代方案、交付内容、风险和限制。','检查价值、实现成本、时间与信任阻力，组织交付、证明和风险说明。','完整方案结构、价值表达与诊断结果。','保障、奖励和承诺必须能兑现；不能只靠夸张文案弥补产品问题。',['pricing','copywriting','product-marketing']],
  'pricing': ['需要设计价格、套餐、计费单位或升级路径。','用户分层、价值来源、成本、现有价格及支付意愿证据。','分析价值指标、套餐区分、调研与验证方式。','定价与打包建议、套餐比较和验证方案。','建议价格不等于最优价格；同时观察收入、激活、留存与支持成本。',['offers','paywalls','customer-research']],
  'content-strategy': ['不知道做什么内容、为谁做，以及如何持续分发。','产品目标、受众问题、现有内容、渠道与制作能力。','划分可搜索与可分享内容，构建主题集群、优先级和复用路径。','内容支柱、选题、制作日历和分发计划。','每个选题对应读者需求和后续行动，避免只追求发布数量。',['seo-audit','copywriting','social']],
  'copywriting': ['需要撰写或重写首页、功能页、定价页等营销文案。','页面目的、读者、产品事实、证明材料和主要行动。','围绕用户利益安排论述，写清标题、证据、疑虑与行动入口。','页面草稿、关键文案备选与写作理由。','事实有来源；每节推进一个要点；不捏造客户和成绩。',['product-marketing','copy-editing','cro']],
  'copy-editing': ['已经有稿件，需要系统改进而非重新定义产品。','现有稿件、目标读者、品牌语气及不能改动的事实。','分轮检查清晰度、表达、相关性、证据和具体性，保留有效内容。','修订稿与重点改动说明。','不在润色时改变事实、范围或承诺；核对新增数字。',['copywriting','product-marketing']],
  'image': ['需要产品图、营销素材、设计文件或图片优化。','用途、尺寸、品牌资料、参考图与可用制作工具。','选择生成、设计或优化路径，准备素材，检查裁切与交付格式。','制作方案、提示词、设计或优化后的图片（工具可用时）。','真实产品图保持真实性；尺寸与格式检查不等于品牌效果已验证。',['ad-creative','social','copywriting']],
  'video': ['需要演示、讲解、短视频或媒体制作流水线。','目标、脚本、素材、时长比例、制作环境与工具。','在程序化视频、AI 生成、数字人或剪辑路径中选择，组织制作与导出。','分镜或制作计划，以及工具支持时的成片。','核对事实、字幕、音画与素材授权；本技能文件不自带视频模型。',['social','ad-creative','image']],
  'seo-audit': ['页面难被搜索发现，或需要检查技术与内容问题。','网址、站点类型、目标查询、权限与现有搜索数据。','检查抓取、索引、页面结构、速度、内容质量及内部链接。','带证据和优先级的审查报告。','只对实际取得的页面和数据下结论；建议不保证收录和排名。',['schema','site-architecture','programmatic-seo']],
  'ai-seo': ['希望内容更容易被 AI 搜索发现、提取与引用。','关键问题、内容与域名、现有可见性和比较对象。','观察实际回答与引用，检查内容结构、可信来源、抓取与机器可读信息。','可见性诊断、内容改进与持续观察方案。','固定查询、日期和平台；不把单次引用、统计关联或文件格式当成保证。',['seo-audit','schema','content-strategy']],
  'programmatic-seo': ['拥有可用于大量页面的真实数据和重复搜索需求。','搜索模式、结构化数据、页面类型、独特价值与维护资源。','选择页面模式，设计模板、URL、内容差异与质量检查。','数据驱动页面方案、模板字段、内链与发布策略。','每页提供独立价值；只替换关键词的批量页面不算完成。',['site-architecture','seo-audit','content-strategy']],
  'site-architecture': ['规划页面层级、导航、URL 或内部链接。','现有内容、站点类型、用户任务与目标页面。','设计页面树、导航区、URL 映射与主题之间的链接。','页面层级、可视站点图、URL 表及导航规则。','用户能找到目标内容；旧网址有迁移策略；XML sitemap 属于 SEO 检查。',['seo-audit','programmatic-seo','schema']],
  'schema': ['需要新增或修复页面结构化数据。','实际页面内容、实体关系、页面类型和已有标记。','选择匹配类型，编写或调整 JSON-LD，检查与页面事实的一致性。','结构化数据实现与验证说明。','通过格式检查不保证富结果；标记不能声称页面不存在的评分或内容。',['seo-audit','ai-seo']],
  'aso': ['优化应用商店页面的发现与下载表现。','商店网址、应用目标、品牌阶段、截图与评价。','取得商店资料，按维度评估元数据、视觉、评价，并可比较竞品。','分项评估和优先改进清单。','评分是方法性判断；未取得图片时不能声称已审查视觉素材。',['copywriting','image','competitor-profiling']],
  'competitors': ['需要替代方案页或诚实、有说服力的竞品比较页。','自身与竞品资料、读者的选择问题、搜索意图。','选择比较形式，核对功能与差异，组织证据和适合人群。','对比或替代方案页面的结构与内容。','不编造竞品弱点；展示适用与不适用条件，注明信息时效。',['competitor-profiling','copywriting','seo-audit']],
  'directory-submissions': ['产品准备进入相关软件目录或评价平台。','正式页面、定位材料、素材、目标目录与已有收录。','检查准备度，选择目录与受众表达，记录提交状态和目标页面。','目录优先级、描述变体、提交追踪与后续指标。','提交不等于收录或获客；上游的数量门槛和效果数字须结合场景核查。',['launch','ai-seo','programmatic-seo']],
  'cro': ['页面或非注册表单没有有效促成期望行动。','页面、转化目标、流量来源、用户反馈与已知数据。','按价值表达、标题、行动入口、层级、信任、疑虑和阻力逐项检查。','快速改动、优先项、实验想法与文案备选。','每个判断能指向页面或证据；建议与已证实原因分开。',['copywriting','signup','ab-testing']],
  'signup': ['账户创建、试用注册或验证步骤流失较多。','注册路径、必填字段、错误反馈、设备与漏斗数据。','检查字段、步骤、信任信息、提交和验证后的体验。','注册审查、改动建议及需要时的表单重设计。','注册成功与产品激活分别衡量，不把更多账户直接等同于更多价值。',['onboarding','analytics','ab-testing']],
  'onboarding': ['用户注册后未体验到产品价值。','首次会话、关键任务、激活定义、用户分组与反馈。','找出首次价值时刻，优化任务顺序、空状态、提示和辅助内容。','引导流程、清单、生命周期协作与激活指标。','激活定义来自实际使用价值；完成引导步骤不一定代表激活。',['signup','emails','analytics']],
  'popups': ['考虑使用弹窗、横幅或浮层促进明确行动。','页面场景、触发条件、目标用户、展示频率与价值内容。','匹配弹窗类型和时机，组织表达、退出行为与实验。','浮层内容、触发与频控建议、衡量方案。','考虑遮挡、误触和可关闭性；收集更多联系方式不等于更好体验。',['cro','lead-magnets','ab-testing']],
  'paywalls': ['需要改善应用内升级、额度限制或付费时机。','免费与付费边界、用户使用状态、套餐与升级路径。','匹配用户已获得的价值，设计触发、比较、说明和可行下一步。','付费入口、升级文案与实验建议。','不凭空更改价格和权限；同时检查升级、流失及支持反馈。',['pricing','onboarding','ab-testing']],
  'ads': ['需要广告渠道策略、账户结构、预算和优化方法。','商业目标、受众、产品方案、预算、账户表现与追踪质量。','选择平台和策略，组织投放结构、创意方向、页面一致性与复盘。','广告计划、审查建议、指标与执行配置方案。','真实投放取决于权限和预算；平台指标须结合收入与增量证据解释。',['ad-creative','cro','attribution']],
  'ad-creative': ['需要多种广告表达，或依据表现迭代素材。','产品证据、受众、平台要求、现有素材与历史结果。','定义角度，批量生成变体，核对规格，分析表现后形成下一轮。','标题与正文、批量素材说明、审阅页或迭代报告。','区分预写素材与实际生成文件；不把某个创意模式视为普适赢家。',['ads','image','video']],
  'social': ['要规划、创作、复用或评估社交内容。','目标平台、受众、品牌、内容资产和制作能力。','设计内容支柱、开头与日历，适配格式，并结合反馈调整。','帖子、内容日历、复用方案和互动建议。','不虚构亲历和用户故事；草稿、排程和已发布状态明确区分。',['content-strategy','video','public-relations']],
  'launch': ['产品、功能或新服务准备对外发布。','定位、准备度、受众、渠道、材料和时间约束。','安排发布前准备、发布期活动与后续使用反馈。','分阶段发布计划、材料清单及跟进安排。','正式地址和素材实际可用；发布热度与持续激活分开记录。',['product-marketing','social','directory-submissions']],
  'public-relations': ['需要媒体报道、新闻表达或记者沟通准备。','具有新闻性的事实、受众、资料和可联系的发言人。','确定新闻角度，准备新闻页、媒体包、提案和跟进方法。','新闻材料、媒体提案与传播衡量方案。','有事实支持新闻性；不把提案当成已报道，不虚构记者关系。',['content-strategy','social','launch']],
  'influencer-marketing': ['需要和创作者或品牌大使合作。','目标受众、合作预算、品牌限制、产品与交付要求。','发现并评估人选，设计合作形式、创意简报与结果记录。','候选评估、合作结构、创意简报和衡量安排。','核实受众匹配与交付条件；粉丝量不是效果证明。',['social','ad-creative','referrals']],
  'events': ['考虑举办、参加、赞助活动或安排演讲。','目标受众、活动角色、资源与后续跟进能力。','选择活动组合，安排会前、会中、会后和内容再利用。','活动计划、责任安排、素材与跟进指标。','参与人数与有效关系、机会推进分开衡量。',['co-marketing','sales-enablement','emails']],
  'co-marketing': ['希望与受众互补的组织开展联合营销。','双方目标、受众重叠、各自资源及合作限制。','评估匹配度，选择联合内容或活动，明确贡献、分工与结果。','合作候选、联合方案与责任和衡量约定。','双方投入和线索使用规则清楚；单方设想不代表对方同意。',['events','content-strategy','referrals']],
  'prospecting': ['需要建立有证据的潜在客户名单。','理想客户条件、排除项、地域或行业、购买或需求信号。','选择 SaaS、B2B、本地企业或需求信号分支，发现、核实、打分与优先排序。','可追溯的候选清单、资格证据和置信度。','不把公开公司信息当成联系许可；不捏造联系人或需求。',['product-marketing','cold-email','customer-research']],
  'cold-email': ['已有合适对象，需要准备首次商业联系邮件。','收件人的相关背景、联系理由、产品价值和可证明材料。','围绕对方的问题写简短、具体的邮件及有价值的跟进。','主题、正文、后续邮件和个性化依据。','避免伪装熟人或虚构了解；准备草稿与实际发送分别处理。',['prospecting','copywriting','sales-enablement']],
  'sales-enablement': ['销售需要一致、能支持决策的材料。','购买角色、异议、销售阶段、产品证据与竞品资料。','围绕买方问题组织演示、单页、比较、异议处理与话术。','销售演示、说明单页、异议文档或演示脚本。','材料中的能力可演示，案例有依据，并标明适用买方。',['product-marketing','competitor-profiling','revops']],
  'revops': ['线索、销售阶段、分配或 CRM 数据口径混乱。','客户生命周期、当前 CRM、负责人、阶段定义与数据。','定义线索资格、评分、路由、管道阶段与自动化条件。','生命周期规则、评分路由方案、管道与数据维护规范。','每个阶段有明确进出条件；重复、缺失数据和责任归属可检查。',['analytics','attribution','sales-enablement']],
  'emails': ['需要欢迎、培育、激活、召回等生命周期邮件。','用户分组、触发事件、产品背景、现有邮件和目标。','安排进入与退出条件、发送节奏、内容顺序及目标行为。','邮件序列、主题正文、触发规则和衡量方案。','避免用户完成目标后仍收到旧步骤；明确退订与投递状态。',['onboarding','churn-prevention','copywriting']],
  'sms': ['短信比其他渠道更适合及时提醒或短流程沟通。','用户订阅状态、场景、地域、平台与发送成本。','选择流程、简短表达、时机和频率，核对同意与停止条件。','短信序列、触发、成本与衡量说明。','规则因地区和渠道变化，实际发送前另行核查；此研究不提供法律结论。',['emails','popups','analytics']],
  'churn-prevention': ['用户主动取消或支付失败造成订阅流失。','流失原因、取消流程、支付平台、使用与用户分组数据。','分开分析主动与非主动流失，设计退出调查、挽留、预警与支付恢复。','保留策略、取消流程、恢复邮件与衡量方案。','保留用户真实选择；短期挽留与长期留存分开观察。',['emails','pricing','analytics']],
  'referrals': ['希望用户推荐或合作伙伴带来新增客户。','现有用户价值、推荐动机、奖励、成本与追踪工具。','设计触发时机、邀请路径、奖励机制、归因与防重复逻辑。','推荐或联盟计划、交付规则与指标。','奖励真实可兑现；评估有效客户、欺诈和成本，而非只看邀请数。',['free-tools','analytics','co-marketing']],
  'marketing-loops': ['一项有明确反馈的工作值得定期重复。','目标信号、数据工具、检查频率、行动条件与状态保存位置。','选择循环，明确步骤、自检、去重、冷却期、停止条件，再交给宿主调度。','循环规格、状态约定、输出与执行节奏。','43 个循环是方法目录；不自带运行中的定时服务，检查不等于每次行动。',['analytics','seo-audit','churn-prevention']],
  'free-tools': ['希望用有实际用途的免费工具吸引相关用户。','受众的具体任务、差异数据、开发资源与维护能力。','评估工具价值、搜索需求、实现范围、留资方式和推广路径。','工具概念、MVP 范围、评估与获客方案。','工具要先有独立用途；维护成本和结果准确性必须可接受。',['lead-magnets','programmatic-seo','analytics']],
  'lead-magnets': ['需要模板、清单或报告帮助用户并建立后续关系。','读者阶段、一个具体问题、资料来源与交付渠道。','选择资料形式、是否留资、获取页面、交付与后续内容。','资料方案、获取与交付流程、推广和衡量方法。','不要用空洞资料换联系方式；下载不等于高质量线索。',['content-strategy','emails','cro']],
  'community-marketing': ['需要建立社区或在现有社区中持续提供价值。','成员共同任务、投入能力、社区规则与业务关系。','选择社区模型，设计参与、成长阶段、运营与健康指标。','社区策略、活动与参与计划、健康评估。','不把社区当成群发广告渠道；人数不能替代持续有用的互动。',['social','customer-research','referrals']],
  'analytics': ['需要知道行为是否被正确记录、数据能否支持决策。','业务问题、主要行动、现有事件、技术栈与数据工具。','从决策反推事件，统一命名、属性、触发及转化定义，调试验证。','追踪计划、事件规范、实现指导和验证记录。','事件实际触发且不重复；成功事件与业务完成对应。',['ab-testing','attribution','revops']],
  'attribution': ['渠道报表互相矛盾，或需要解释哪些投入带来转化。','要做的决策、业务周期、不同报表、身份和来源数据。','比较模型与口径，检查身份连接、盲区、窗口和第一方记录。','归因解读、差异解释、置信度及下一步测量建议。','归因分配不等于因果增量；把缺失和不确定性明确写出。',['analytics','ads','revops']],
  'ab-testing': ['有可检验的改动假设，或想建设持续实验方法。','真实基线、流量、目标变化、实现约束和分析方法。','预先设定假设、样本、主要与护栏指标，实施核对后按计划解释结果。','实验设计、记录、结果分析和可复用经验。','避免反复窥视后提前停止；证据不足是合法结论。',['analytics','cro','marketing-loops']]
}).map(([name, values]) => [name, Object.fromEntries(['when','input','method','output','check','related'].map((key, i) => [key, values[i]]))]));
